#### Configuration Loading Pattern

```python
import os
import yaml
import json
from pathlib import Path
from typing import Dict, Any

class ConfigurationManager:
    def __init__(self, app_name: str, environment: str):
        self.app_name = app_name
        self.environment = environment
        self.config_paths = [
            f"/etc/{app_name}/config.yaml",
            f"./config/default.yaml",
            f"./config/{environment}.yaml",
            f"./config/local.yaml"
        ]

    def load_configuration(self) -> AppConfig:
        """Load configuration from multiple sources with proper precedence"""
        config_data = {}

        # Load from configuration files
        for config_path in self.config_paths:
            if Path(config_path).exists():
                with open(config_path, 'r') as f:
                    file_config = yaml.safe_load(f)
                    if file_config:
                        config_data.update(file_config)

        # Override with environment variables
        config_data.update(self._load_from_env())

        # Load secrets from secure storage
        config_data.update(self._load_secrets())

        return AppConfig(**config_data)

    def _load_from_env(self) -> Dict[str, Any]:
        """Load configuration from environment variables"""
        env_config = {}
        prefix = f"{self.app_name.upper()}_"

        for key, value in os.environ.items():
            if key.startswith(prefix):
                config_key = key[len(prefix):].lower()
                # Handle nested configuration
                if "__" in config_key:
                    self._set_nested_value(env_config, config_key, value)
                else:
                    env_config[config_key] = value

        return env_config

    def _load_secrets(self) -> Dict[str, Any]:
        """Load secrets from secure storage"""
        secrets = {}

        # Load from HashiCorp Vault, Azure Key Vault, etc.
        vault_client = self._get_vault_client()
        if vault_client:
            secret_data = vault_client.get_secret(f"{self.app_name}/{self.environment}")
            secrets.update(secret_data)

        return secrets

    def _set_nested_value(self, config: Dict, key: str, value: str):
        """Set nested configuration value from flattened key"""
        keys = key.split("__")
        current = config

        for k in keys[:-1]:
            if k not in current:
                current[k] = {}
            current = current[k]

        current[keys[-1]] = value
