#### Configuration Encryption

```python
from cryptography.fernet import Fernet
import base64
import os

class ConfigurationEncryption:
    def __init__(self):
        # Key should be stored securely and rotated regularly
        key = os.getenv("CONFIG_ENCRYPTION_KEY")
        if not key:
            raise ValueError("CONFIG_ENCRYPTION_KEY environment variable required")

        self.cipher = Fernet(key.encode())

    def encrypt_config_value(self, value: str) -> str:
        """Encrypt a configuration value"""
        encrypted_value = self.cipher.encrypt(value.encode())
        return base64.b64encode(encrypted_value).decode()

    def decrypt_config_value(self, encrypted_value: str) -> str:
        """Decrypt a configuration value"""
        encrypted_bytes = base64.b64decode(encrypted_value.encode())
        decrypted_value = self.cipher.decrypt(encrypted_bytes)
        return decrypted_value.decode()

    def is_encrypted(self, value: str) -> bool:
        """Check if a value is encrypted"""
        return value.startswith("enc:")

    def process_config(self, config: Dict[str, Any]) -> Dict[str, Any]:
        """Process configuration and decrypt encrypted values"""
        processed_config = {}

        for key, value in config.items():
            if isinstance(value, str) and self.is_encrypted(value):
                # Remove 'enc:' prefix and decrypt
                encrypted_value = value[4:]
                processed_config[key] = self.decrypt_config_value(encrypted_value)
            elif isinstance(value, dict):
                processed_config[key] = self.process_config(value)
            else:
                processed_config[key] = value

        return processed_config
