from pydantic import BaseModel, validator, Field
from typing import Optional, List, Dict, Any
import re

class DatabaseConnectionConfig(BaseModel):
    host: str = Field(..., description="Database hostname or IP")
    port: int = Field(5432, ge=1, le=65535, description="Database port")
    database: str = Field(..., description="Database name")
    username: str = Field(..., description="Database username")
    password: str = Field(..., description="Database password")
    ssl_mode: str = Field("require", description="SSL connection mode")
    connection_timeout: int = Field(30, ge=1, le=300, description="Connection timeout in seconds")

    @validator('host')
    def validate_host(cls, v):
        # Validate hostname or IP address
        hostname_pattern = r'^[a-zA-Z0-9]([a-zA-Z0-9\-]{0,61}[a-zA-Z0-9])?(\.[a-zA-Z0-9]([a-zA-Z0-9\-]{0,61}[a-zA-Z0-9])?)*$'
        ip_pattern = r'^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$'

        if not (re.match(hostname_pattern, v) or re.match(ip_pattern, v)):
            raise ValueError('Invalid hostname or IP address')
        return v

    @validator('ssl_mode')
    def validate_ssl_mode(cls, v):
        valid_modes = ['disable', 'allow', 'prefer', 'require', 'verify-ca', 'verify-full']
        if v not in valid_modes:
            raise ValueError(f'ssl_mode must be one of {valid_modes}')
        return v

class ConfigurationValidator:
    def __init__(self):
        self.validation_rules = {}

    def validate_configuration(self, config: Dict[str, Any]) -> List[str]:
        """Validate entire configuration and return list of errors"""
        errors = []

        # Validate required fields
        required_fields = ['app.name', 'app.version', 'database.host']
        for field in required_fields:
            if not self._get_nested_value(config, field):
                errors.append(f"Required field missing: {field}")

        # Validate database configuration
        if 'database' in config:
            try:
                DatabaseConnectionConfig(**config['database'])
            except Exception as e:
                errors.append(f"Database configuration error: {str(e)}")

        # Validate environment-specific requirements
        environment = config.get('app', {}).get('environment')
        if environment == 'production':
            prod_errors = self._validate_production_config(config)
            errors.extend(prod_errors)

        return errors

    def _validate_production_config(self, config: Dict[str, Any]) -> List[str]:
        """Additional validation for production environment"""
        errors = []

        # Ensure debug is disabled in production
        if config.get('app', {}).get('debug', False):
            errors.append("Debug mode must be disabled in production")

        # Ensure SSL is enabled for database
        ssl_mode = config.get('database', {}).get('ssl_mode', '')
        if ssl_mode in ['disable', 'allow']:
            errors.append("Database SSL must be enabled in production")

        # Validate log level
        log_level = config.get('logging', {}).get('level', 'INFO')
        if log_level == 'DEBUG':
            errors.append("Debug logging should not be enabled in production")

        return errors

    def _get_nested_value(self, config: Dict, key_path: str) -> Any:
        """Get value from nested dictionary using dot notation"""
        keys = key_path.split('.')
        value = config

        for key in keys:
            if isinstance(value, dict) and key in value:
                value = value[key]
            else:
                return None

        return value
