#### Tenant-Specific Configuration

```python
from typing import Dict, Any, Optional

class TenantConfigurationManager:
    def __init__(self, base_config: AppConfig):
        self.base_config = base_config
        self.tenant_configs = {}

    def get_tenant_config(self, tenant_id: str) -> AppConfig:
        """Get configuration for specific tenant"""
        if tenant_id not in self.tenant_configs:
            self.tenant_configs[tenant_id] = self._load_tenant_config(tenant_id)

        return self.tenant_configs[tenant_id]

    def _load_tenant_config(self, tenant_id: str) -> AppConfig:
        """Load tenant-specific configuration"""
        # Start with base configuration
        config_data = self.base_config.dict()

        # Load tenant-specific overrides
        tenant_overrides = self._get_tenant_overrides(tenant_id)
        config_data.update(tenant_overrides)

        # Load tenant feature flags
        feature_flags = self._get_tenant_feature_flags(tenant_id)
        config_data['feature_flags'] = feature_flags

        return AppConfig(**config_data)

    def _get_tenant_overrides(self, tenant_id: str) -> Dict[str, Any]:
        """Get tenant-specific configuration overrides"""
        # Load from database, configuration service, etc.
        tenant_config_path = f"config/tenants/{tenant_id}.yaml"

        if Path(tenant_config_path).exists():
            with open(tenant_config_path, 'r') as f:
                return yaml.safe_load(f) or {}

        return {}

    def _get_tenant_feature_flags(self, tenant_id: str) -> List[str]:
        """Get feature flags enabled for tenant"""
        # This could integrate with a feature flag service
        tenant_features = {
            "tenant_1": ["premium_features", "advanced_analytics"],
            "tenant_2": ["basic_features"],
            "tenant_3": ["premium_features", "beta_features"]
        }

        return tenant_features.get(tenant_id, ["basic_features"])

# Usage in application
class TenantAwareApplication:
    def __init__(self):
        self.base_config = ConfigurationManager("myapp", "production").load_configuration()
        self.tenant_manager = TenantConfigurationManager(self.base_config)

    def handle_request(self, request):
        tenant_id = self.extract_tenant_id(request)
        tenant_config = self.tenant_manager.get_tenant_config(tenant_id)

        # Use tenant-specific configuration
        return self.process_with_config(request, tenant_config)
```
